package com.jnapanam.sportszone.training.dto;import com.jnapanam.sportszone.training.model.TrainingBatch;import java.math.BigDecimal;import java.time.*;import java.util.*;public record BatchResponse(UUID id,String programCode,String facilityCode,String coachName,String name,LocalDate startDate,LocalDate endDate,LocalTime startTime,LocalTime endTime,Set<DayOfWeek>daysOfWeek,int capacity,long available,BigDecimal fee,String status){public static BatchResponse from(TrainingBatch b,long enrolled){return new BatchResponse(b.getId(),b.getProgram().getCode(),b.getFacility().getCode(),b.getCoach()==null?null:b.getCoach().getFullName(),b.getName(),b.getStartDate(),b.getEndDate(),b.getStartTime(),b.getEndTime(),b.getDaysOfWeek(),b.getCapacity(),Math.max(0,b.getCapacity()-enrolled),b.getFee(),b.getStatus().name());}}
